// Package render translates validated Markitect resources into readable views
// and provider entrypoints. It performs no filesystem writes.
package render

import (
	"encoding/json"
	"fmt"
	"path"
	"sort"
	"strconv"
	"strings"
	"unicode"
	"unicode/utf8"

	"markitect/internal/core"
)

// Marker is embedded in every generated file so ownership remains visible.
const Marker = "Generated by Markitect"

// Generate returns deterministic generated files keyed by repository-relative
// POSIX paths. The caller owns safe filesystem writes.
func Generate(g *core.Graph) (map[string][]byte, error) {
	if g == nil {
		return nil, fmt.Errorf("graph is nil")
	}
	resources := make([]*core.Resource, 0, len(g.Resources))
	for _, r := range g.Resources {
		if r == nil {
			return nil, fmt.Errorf("graph contains a nil resource")
		}
		resources = append(resources, r)
	}
	sort.Slice(resources, func(i, j int) bool {
		if resources[i].Path != resources[j].Path {
			return resources[i].Path < resources[j].Path
		}
		return resources[i].Key() < resources[j].Key()
	})

	outputs := map[string][]byte{}
	canonical := map[string]*core.Resource{}
	for _, r := range resources {
		if err := validRepoPath(r.Path); err != nil {
			return nil, fmt.Errorf("resource %s source path: %w", r.Key(), err)
		}
		folded := foldPath(r.Path)
		if prior := canonical[folded]; prior != nil {
			return nil, fmt.Errorf("source path collision: %q and %q", prior.Path, r.Path)
		}
		canonical[folded] = r
		if r.Kind == "Project" {
			continue
		}
		view := companionPath(r.Path)
		content, err := renderCompanion(r, view, g)
		if err != nil {
			return nil, err
		}
		if err := add(outputs, view, content); err != nil {
			return nil, err
		}
	}

	profile, targets := "", map[string]bool{}
	if g.Project != nil {
		profile = strings.ToLower(g.Project.Spec.Profile)
		for _, target := range g.Project.Spec.Targets {
			target = strings.ToLower(target)
			if target != "codex" && target != "claude" {
				return nil, fmt.Errorf("unsupported provider target %q", target)
			}
			targets[target] = true
		}
	}
	// Konfyra's existing Python renderer remains the provider-output owner
	// during the pilot. Markitect still produces adjacent readable views.
	if profile == "konfyra" && len(targets) == 0 {
		return checkCollisions(outputs, canonical)
	}
	if targets["codex"] || targets["claude"] {
		for _, r := range resources {
			if r.Kind == "Project" {
				continue
			}
			switch r.Kind {
			case "Skill":
				if targets["codex"] {
					p := ".agents/skills/" + r.Metadata.Name + "/SKILL.md"
					if err := add(outputs, p, renderSkill(r, p, g)); err != nil {
						return nil, err
					}
				}
				if targets["claude"] {
					p := ".claude/skills/" + r.Metadata.Name + "/SKILL.md"
					if err := add(outputs, p, renderSkill(r, p, g)); err != nil {
						return nil, err
					}
				}
			case "Agent":
				if targets["codex"] {
					p := ".codex/agents/" + r.Metadata.Name + ".toml"
					if err := add(outputs, p, renderCodexAgent(r, p)); err != nil {
						return nil, err
					}
				}
				if targets["claude"] {
					p := ".claude/agents/" + r.Metadata.Name + ".md"
					if err := add(outputs, p, renderClaudeAgent(r, p, g)); err != nil {
						return nil, err
					}
				}
			}
		}
	}
	if targets["claude"] {
		ruleOutputs, err := renderRules(resources, g)
		if err != nil {
			return nil, err
		}
		for p, b := range ruleOutputs {
			if err := add(outputs, p, b); err != nil {
				return nil, err
			}
		}
	}
	return checkCollisions(outputs, canonical)
}

func renderCompanion(r *core.Resource, target string, g *core.Graph) ([]byte, error) {
	if g.Project != nil && strings.EqualFold(g.Project.Spec.Profile, "konfyra") {
		return renderKonfyraCompanion(r)
	}
	var b strings.Builder
	b.WriteString("<!-- " + Marker + "; source: " + r.Path + " -->\n")
	b.WriteString("# " + r.Kind + ": " + r.Metadata.Name + "\n\n")
	if r.Spec.Description != "" {
		b.WriteString("**Description:** " + r.Spec.Description + "\n\n")
	}
	if r.Spec.Text != "" {
		b.WriteString(r.Spec.Text)
		if !strings.HasSuffix(r.Spec.Text, "\n") {
			b.WriteByte('\n')
		}
	}
	links := dependencyLinks(r, target, g)
	if len(links) > 0 {
		b.WriteString("\n## Dependencies\n\n")
		for _, link := range links {
			b.WriteString("- [" + link.label + "](" + link.path + ")\n")
		}
	}
	return []byte(b.String()), nil
}

// renderKonfyraCompanion retains the frontmatter contract consumed by the
// repository's current Python migration renderer. The body is exactly spec.text.
func renderKonfyraCompanion(r *core.Resource) ([]byte, error) {
	var b strings.Builder
	switch r.Kind {
	case "Skill":
		if err := validateLegacyDescription(r.Spec.Description); err != nil {
			return nil, fmt.Errorf("Konfyra Skill %q description: %w", r.Metadata.Name, err)
		}
		b.WriteString("---\nname: " + r.Metadata.Name + "\ndescription: " + r.Spec.Description + "\n---\n")
	case "Agent":
		metadata, err := konfyraAgentMetadata(r)
		if err != nil {
			return nil, err
		}
		encoded, _ := json.Marshal(metadata)
		b.WriteString("---\n" + string(encoded) + "\n---\n")
	}
	b.WriteString("<!-- " + Marker + "; source: " + r.Path + " -->\n")
	b.WriteString(r.Spec.Text)
	return []byte(b.String()), nil
}

func validateLegacyDescription(description string) error {
	trimmed := strings.TrimSpace(description)
	if description == "" || trimmed != description || strings.ContainsAny(description, "\r\n\t") || strings.Contains(description, " #") || strings.Contains(description, ": ") || strings.HasSuffix(description, ":") {
		return fmt.Errorf("must be a non-empty, single-line plain description supported by the legacy adapter")
	}
	if strings.HasPrefix(description, `"`) || strings.HasSuffix(description, `"`) || strings.HasPrefix(description, "'") || strings.HasSuffix(description, "'") {
		return fmt.Errorf("must not begin or end with a quote because the legacy adapter strips surrounding quotes")
	}
	first, _ := utf8.DecodeRuneInString(description)
	if !unicode.IsLetter(first) && first != '_' {
		return fmt.Errorf("must begin with a letter or underscore to remain a plain string for the legacy adapter")
	}
	switch strings.ToLower(description) {
	case "true", "false", "null", "~", "yes", "no", "on", "off":
		return fmt.Errorf("must be a plain string value supported by the legacy adapter")
	}
	return nil
}

func konfyraAgentMetadata(r *core.Resource) (map[string]any, error) {
	codex := map[string]string{}
	claude := map[string]any{}
	if p := r.Spec.Providers.Codex; p != nil {
		if p.Model == "" || p.Effort == "" || p.Sandbox == "" {
			return nil, fmt.Errorf("Konfyra agent %q needs complete Codex metadata for companion compatibility", r.Metadata.Name)
		}
		codex["model"] = p.Model
		codex["model_reasoning_effort"] = p.Effort
		codex["sandbox_mode"] = p.Sandbox
	}
	if p := r.Spec.Providers.Claude; p != nil {
		if p.Model == "" || p.Effort == "" || p.PermissionMode == "" {
			return nil, fmt.Errorf("Konfyra agent %q needs complete Claude metadata for companion compatibility", r.Metadata.Name)
		}
		claude["model"] = p.Model
		claude["effort"] = p.Effort
		claude["permissionMode"] = p.PermissionMode
		if len(p.Tools) > 0 {
			claude["tools"] = p.Tools
		}
		if len(p.DisallowedTools) > 0 {
			claude["disallowedTools"] = p.DisallowedTools
		}
		if p.MaxTurns > 0 {
			claude["maxTurns"] = p.MaxTurns
		}
	}
	if r.Spec.Providers.Codex == nil || r.Spec.Providers.Claude == nil {
		return nil, fmt.Errorf("Konfyra agent %q needs Codex and Claude metadata for companion compatibility", r.Metadata.Name)
	}
	return map[string]any{"name": r.Metadata.Name, "description": r.Spec.Description, "codex": codex, "claude": claude}, nil
}

type dependencyLink struct{ label, path string }

func dependencyLinks(r *core.Resource, from string, g *core.Graph) []dependencyLink {
	type typedRef struct {
		ref  core.Ref
		kind string
	}
	refs := make([]typedRef, 0, len(r.Spec.Rules)+len(r.Spec.Uses)+len(r.Spec.Needs)+len(r.Spec.Implements))
	for _, ref := range r.Spec.Rules {
		refs = append(refs, typedRef{ref, "Rule"})
	}
	for _, ref := range r.Spec.Uses {
		refs = append(refs, typedRef{ref, ""})
	}
	for _, ref := range r.Spec.Needs {
		refs = append(refs, typedRef{ref, "Contract"})
	}
	for _, ref := range r.Spec.Implements {
		refs = append(refs, typedRef{ref, "Contract"})
	}
	seen := map[string]bool{}
	links := make([]dependencyLink, 0, len(refs))
	for _, item := range refs {
		ref := item.ref
		key := ref.Key(r.Metadata.Namespace, item.kind)
		if seen[key] {
			continue
		}
		seen[key] = true
		dep := findResource(g, ref, r.Metadata.Namespace, item.kind)
		if dep == nil || dep.Kind == "Project" || dep.Path == "" {
			continue
		}
		companion := companionPath(dep.Path)
		links = append(links, dependencyLink{dep.Kind + ": " + dep.Metadata.Name, relative(from, companion)})
	}
	sort.Slice(links, func(i, j int) bool { return links[i].label < links[j].label })
	return links
}

func renderSkill(r *core.Resource, target string, g *core.Graph) []byte {
	var b strings.Builder
	b.WriteString("---\nname: " + yamlQuote(r.Metadata.Name) + "\ndescription: " + yamlQuote(r.Spec.Description) + "\n---\n\n")
	b.WriteString("<!-- " + Marker + "; source: " + relative(target, r.Path) + " -->\n\n")
	b.WriteString("Read the [canonical skill definition](" + relative(target, companionPath(r.Path)) + ") before acting.\n")
	links := dependencyLinks(r, target, g)
	if len(links) > 0 {
		b.WriteString("\n## Dependencies\n\n")
		for _, link := range links {
			b.WriteString("- [" + link.label + "](" + link.path + ")\n")
		}
	}
	return []byte(b.String())
}

func renderCodexAgent(r *core.Resource, target string) []byte {
	p := r.Spec.Providers.Codex
	var b strings.Builder
	b.WriteString("# " + Marker + "; source: " + relative(target, r.Path) + "\n")
	if p != nil {
		writeTOMLString(&b, "name", r.Metadata.Name)
		writeTOMLString(&b, "description", r.Spec.Description)
		if p.Model != "" {
			writeTOMLString(&b, "model", p.Model)
		}
		if p.Effort != "" {
			writeTOMLString(&b, "model_reasoning_effort", p.Effort)
		}
		if p.Sandbox != "" {
			writeTOMLString(&b, "sandbox_mode", p.Sandbox)
		}
	}
	writeTOMLString(&b, "developer_instructions", "Read the canonical [agent view]("+relative(target, companionPath(r.Path))+") and follow its stated scope.")
	return []byte(b.String())
}

func renderClaudeAgent(r *core.Resource, target string, g *core.Graph) []byte {
	p := r.Spec.Providers.Claude
	var b strings.Builder
	b.WriteString("---\nname: " + yamlQuote(r.Metadata.Name) + "\ndescription: " + yamlQuote(r.Spec.Description) + "\n")
	if p != nil {
		if p.Model != "" {
			b.WriteString("model: " + yamlQuote(p.Model) + "\n")
		}
		if p.Effort != "" {
			b.WriteString("effort: " + yamlQuote(p.Effort) + "\n")
		}
		if p.PermissionMode != "" {
			b.WriteString("permissionMode: " + yamlQuote(p.PermissionMode) + "\n")
		}
		if len(p.Tools) > 0 {
			b.WriteString("tools: " + yamlArray(p.Tools) + "\n")
		}
		if len(p.DisallowedTools) > 0 {
			b.WriteString("disallowedTools: " + yamlArray(p.DisallowedTools) + "\n")
		}
		if p.MaxTurns > 0 {
			fmt.Fprintf(&b, "maxTurns: %d\n", p.MaxTurns)
		}
	}
	b.WriteString("---\n\n<!-- " + Marker + "; source: " + relative(target, r.Path) + " -->\n\n")
	b.WriteString("Read the [canonical agent view](" + relative(target, companionPath(r.Path)) + ") before acting.\n")
	for _, link := range dependencyLinks(r, target, g) {
		b.WriteString("- [" + link.label + "](" + link.path + ")\n")
	}
	return []byte(b.String())
}

func renderRules(resources []*core.Resource, g *core.Graph) (map[string][]byte, error) {
	out := map[string][]byte{}
	if g.Project != nil && g.Project.Spec.RuleAdapters != nil {
		names := make([]string, 0, len(g.Project.Spec.RuleAdapters))
		for name := range g.Project.Spec.RuleAdapters {
			names = append(names, name)
		}
		sort.Strings(names)
		for _, name := range names {
			refs := g.Project.Spec.RuleAdapters[name]
			var b strings.Builder
			b.WriteString("<!-- " + Marker + " -->\n# " + title(name) + "\n\n")
			for _, ref := range refs {
				r := findResource(g, ref, "", "Rule")
				if r == nil {
					return nil, fmt.Errorf("rule adapter %q references unresolved rule %q", name, ref.Name)
				}
				b.WriteString("- [" + r.Metadata.Name + "](" + relative(".claude/rules/"+name+".md", companionPath(r.Path)) + ")\n")
			}
			out[".claude/rules/"+name+".md"] = []byte(b.String())
		}
		return out, nil
	}
	if g.Project == nil || strings.ToLower(g.Project.Spec.Profile) != "cockpit" {
		return out, nil
	}
	allowed := map[string]string{"cockpit-general": "general", "cockpit-consiliari": "consiliari"}
	for _, area := range g.Project.Spec.Areas {
		scope, ok := allowed[area.Name]
		if !ok {
			continue
		}
		for _, ref := range area.Rules {
			r := findResource(g, ref, area.Name, "Rule")
			if r == nil {
				return nil, fmt.Errorf("area %q references unresolved rule %q", area.Name, ref.Name)
			}
			name := scope + "-" + r.Metadata.Name
			p := ".claude/rules/" + name + ".md"
			out[p] = []byte("<!-- " + Marker + "; source: " + relative(p, r.Path) + " -->\n# " + title(r.Metadata.Name) + "\n\nRead the [canonical rule view](" + relative(p, companionPath(r.Path)) + ") and apply it only within its stated scope.\n")
		}
	}
	return out, nil
}

func findResource(g *core.Graph, ref core.Ref, namespace, kind string) *core.Resource {
	if ref.Kind != "" {
		kind = ref.Kind
	}
	if ref.Namespace != "" {
		namespace = ref.Namespace
	}
	return g.Resources[namespace+"/"+kind+"/"+ref.Name]
}

func companionPath(source string) string {
	ext := path.Ext(source)
	if ext == "" {
		return source + ".md"
	}
	return strings.TrimSuffix(source, ext) + ".md"
}

func relative(fromFile, toFile string) string {
	return relativePath(path.Dir(fromFile), toFile)
}

func relativePath(fromDir, to string) string {
	// Implement POSIX relative paths without consulting the host OS.
	from := strings.Split(strings.Trim(fromDir, "/"), "/")
	toParts := strings.Split(strings.Trim(to, "/"), "/")
	if len(from) == 1 && from[0] == "" {
		from = nil
	}
	i := 0
	for i < len(from) && i < len(toParts) && from[i] == toParts[i] {
		i++
	}
	parts := make([]string, 0, len(from)-i+len(toParts)-i)
	for range from[i:] {
		parts = append(parts, "..")
	}
	parts = append(parts, toParts[i:]...)
	if len(parts) == 0 {
		return "."
	}
	return strings.Join(parts, "/")
}

func add(outputs map[string][]byte, name string, data []byte) error {
	if err := validRepoPath(name); err != nil {
		return fmt.Errorf("invalid output path %q: %w", name, err)
	}
	if _, exists := outputs[name]; exists {
		return fmt.Errorf("duplicate generated output %q", name)
	}
	outputs[name] = data
	return nil
}

func checkCollisions(outputs map[string][]byte, sources map[string]*core.Resource) (map[string][]byte, error) {
	seen := map[string]string{}
	for source := range sources {
		seen[foldPath(source)] = "source " + source
	}
	paths := make([]string, 0, len(outputs))
	for p := range outputs {
		paths = append(paths, p)
	}
	sort.Strings(paths)
	for _, p := range paths {
		key := foldPath(p)
		if prior, ok := seen[key]; ok {
			return nil, fmt.Errorf("output path collision: %s conflicts with %q", prior, p)
		}
		seen[key] = "output " + p
	}
	return outputs, nil
}

func validRepoPath(p string) error {
	if p == "" || strings.ContainsAny(p, "\\:\x00") || strings.HasPrefix(p, "/") || path.Clean(p) != p || p == "." || strings.HasPrefix(p, "../") {
		return fmt.Errorf("path must be repository-relative and normalized")
	}
	for _, part := range strings.Split(p, "/") {
		if part == "" || part == "." || part == ".." {
			return fmt.Errorf("path contains unsafe component")
		}
	}
	return nil
}

func foldPath(p string) string  { return strings.ToLower(p) }
func yamlQuote(s string) string { return strconv.Quote(s) }
func yamlArray(values []string) string {
	quoted := make([]string, len(values))
	for i, v := range values {
		quoted[i] = yamlQuote(v)
	}
	return "[" + strings.Join(quoted, ", ") + "]"
}
func writeTOMLString(b *strings.Builder, key, value string) {
	fmt.Fprintf(b, "%s = %s\n", key, strconv.Quote(value))
}
func writeTOMLArray(b *strings.Builder, key string, values []string) {
	fmt.Fprintf(b, "%s = %s\n", key, yamlArray(values))
}
func title(s string) string { return strings.ReplaceAll(s, "-", " ") }
